SELECT QUARTER(s.opened_date) AS opened_quarter, COUNT(DISTINCT o.shipping_fee) AS unique_stores, ROUND((100 * SUM(CASE WHEN o.channel = 'partner' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_partner FROM orders o RIGHT OUTER JOIN customers c ON o.customer_id = c.id INNER JOIN stores s ON s.id = o.store_id WHERE c.email LIKE '%@outlook.com' GROUP BY QUARTER(s.opened_date) HAVING pct_partner > 56;
